styles.css:
body { background: #0b0b10; color: #f5f0e6; font-family: 'Arial Narrow', Impact, sans-serif; }
.qb-page-title { color: #e8b34b; text-transform: uppercase; letter-spacing: 0.3em; text-align: center; border-bottom: 3px solid #e8b34b; }
.qb-quote { background: #14141d; border: 1px solid #3a3a4d; border-top: 6px solid #e8b34b; padding: 32px 28px; text-align: center; }
.qb-said-name { color: #e8b34b; font-weight: bold; text-transform: uppercase; }
.qb-said-text { color: #f5f0e6; font-size: 1.35em; line-height: 1.5; }
.qb-action-line { color: #b8aec9; font-style: italic; }
.qb-timestamp { color: #6b6480; }
.qb-other-line { color: #cfc8dd; }

body { background: #ffffff; color: #111111; font-family: Georgia, 'Times New Roman', serif; }
.qb-page-title { color: #111111; border-bottom: 1px solid #999999; }
.qb-quote { background: #ffffff; border: none; border-bottom: 1px solid #cccccc; padding: 14px 0; }
.qb-said-name { color: #111111; font-weight: bold; }
.qb-said-text { color: #111111; }
.qb-action-line { color: #444444; font-style: italic; }
.qb-timestamp { color: #777777; }
.qb-other-line { color: #222222; }
